import{e as s,f as i,n as o}from"./index-CIoZzya4.js";const l={async mount(r){await c(r)}};async function c(r){r.innerHTML='<div class="rrr-loading">Loading integration status…</div>';const n=await s("/api/mobile/v1/rrr/integrations"),t=n.ok?(n.data.integrations||[]).find(e=>e.type==="ebioserver"):null,d=n.ok?n.data.devices||[]:[];r.innerHTML=`<main class="rrr-page rrr-detail"><header class="rrr-header"><button id="rrr-back">←</button><div class="rrr-brand"><b>RRR</b><span>Integrations</span></div></header><h1>eSSL eBioServer</h1><p>Your phone manages the connection through RRR. eBioServer credentials stay on the gym PC.</p><section class="rrr-panel"><h2>${i(t?.status||"Not configured")}</h2><p>${t?.device_serial?`Selected device: ${i(t.device_name||t.device_serial)} (${i(t.device_serial)})`:"Pair the eBioServer Bridge from the licensed gym PC."}</p><p>Commissioning: ${i(t?.commissioning_status||"not started")} · ${t?.records_synced||0} records synced · ${t?.unmapped_records||0} unmapped</p>${d.length?`<h3>Devices reported by the gym-PC connector</h3>${d.map(e=>`<p>${i(e.name)} · ${i(e.serial_number)} · ${i(e.status||"unknown")} ${e.selected?"· Selected":`<button data-select-device="${e.id}">Select device</button>`}</p>`).join("")}`:"<p>No device inventory reported yet. Keep the paired connector running; it checks eBioServer through the gym PC.</p>"}<button id="rrr-pair">Generate pairing code</button><button id="rrr-mappings">Review unmapped punches</button><button id="rrr-rules">Signal thresholds</button><div id="rrr-pair-code"></div>${t?.commissioning_status==="attendance_verified"&&!t?.commands_enabled?'<button id="rrr-commission">Enable after supervised door test</button>':""}</section></main>`,r.querySelector("#rrr-back")?.addEventListener("click",()=>o.switchTab("dashboard")),r.querySelector("#rrr-mappings")?.addEventListener("click",()=>o.push("rrr-mappings")),r.querySelector("#rrr-rules")?.addEventListener("click",()=>o.push("rrr-rules")),r.querySelector("#rrr-pair")?.addEventListener("click",async()=>{const e=await s("/api/mobile/v1/rrr/integrations/ebioserver/pairing",{method:"POST",body:{}}),a=r.querySelector("#rrr-pair-code");a.textContent=e.ok?`Pairing code: ${e.data.pairing_code} (expires ${new Date(e.data.expires_at).toLocaleTimeString()})`:"Could not create pairing code."}),r.querySelectorAll("[data-select-device]").forEach(e=>e.addEventListener("click",async()=>{const a=await s(`/api/mobile/v1/rrr/integrations/${t.id}/device`,{method:"POST",body:{device_id:Number(e.dataset.selectDevice)}});a.ok?await c(r):alert(a.error?.message||"Could not select the device.")})),r.querySelector("#rrr-commission")?.addEventListener("click",async()=>{if(!confirm("Confirm that a supervised physical door test passed."))return;(await s(`/api/mobile/v1/rrr/integrations/${t.id}/commission`,{method:"POST",body:{physical_test_passed:!0}})).ok&&c(r)})}export{l as default};
